<script setup lang="ts">
import {ref,reactive,onMounted,computed,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import Icon from '../components/Icon.vue'
import {state,t,api,wp,notify,refreshWorkspace,adminAccess,fmt} from '../state'
const route=useRoute(),router=useRouter(),tab=ref(String(route.query.tab||'team')),team=ref<any>({members:[],invitations:[]}),busy=ref(false),inviteUrl=ref(''),testResult=ref<any>(null),invite=reactive({email:'',role:'viewer'}),displayName=ref(state.user.name)
const model=reactive({mode:state.workspace.settings.model?.mode||'case',model:state.workspace.settings.model?.model||'qwen/qwen3.6-35b-a3b',base_url:state.workspace.settings.model?.base_url||'',api_key:''})
const prefs=reactive({email_alerts:state.user.preferences.email_alerts||false,email_briefs:state.user.preferences.email_briefs||false})
const schedules=ref<string[]>(state.workspace.settings.scheduled_briefs||[])
const tabs=computed(()=>[{id:'team',label:t('Team & roles','Команда и роли'),icon:'Users'},{id:'model',label:t('Model connection','Подключение модели'),icon:'Cpu'},{id:'delivery',label:t('Brief schedules','Расписание сводок'),icon:'CalendarClock'},{id:'profile',label:t('My account','Мой аккаунт'),icon:'UserRound'}])
watch(()=>route.query.tab,v=>{if(v)tab.value=String(v)})
onMounted(async()=>{try{team.value=await api(wp('/members'))}catch(e:any){notify(e.message,true)}})
async function sendInvite(){busy.value=true;try{const r=await api(wp('/invites'),{method:'POST',body:invite});inviteUrl.value=r.invite_url;invite.email='';team.value=await api(wp('/members'));notify(r.delivery_enabled?t('Invitation queued for email delivery.','Приглашение поставлено в очередь отправки.'):t('Invitation created. Email delivery is disabled; use the invitation link.','Приглашение создано. Отправка писем отключена; используйте ссылку.'))}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function roleChange(m:any,event:Event){try{await api(wp('/members/'+m.id),{method:'PATCH',body:{role:(event.target as HTMLSelectElement).value}});team.value=await api(wp('/members'));notify(t('Role updated.','Роль обновлена.'))}catch(e:any){notify(e.message,true);team.value=await api(wp('/members'))}}
async function remove(m:any){try{await api(wp('/members/'+m.id),{method:'DELETE'});team.value=await api(wp('/members'));notify(t('Member removed from this workspace.','Участник удалён из пространства.'))}catch(e:any){notify(e.message,true)}}
async function saveModel(){busy.value=true;testResult.value=null;try{state.workspace=await api(wp('/model'),{method:'PUT',body:model});model.api_key='';notify(t('Model connection saved. The key is encrypted and never returned to the browser.','Подключение сохранено. Ключ зашифрован и не возвращается в браузер.'))}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function test(){busy.value=true;try{testResult.value=await api(wp('/model/test'),{method:'POST'});notify(testResult.value.ok?t('Connection verified.','Подключение проверено.'):t('The connection returned an unexpected response.','Подключение вернуло неожиданный ответ.'),!testResult.value.ok)}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function saveAccount(){busy.value=true;try{state.user=await api('/auth/me',{method:'PATCH',body:{name:displayName.value,preferences:{...prefs,locale:state.locale}}});notify(t('Account preferences saved.','Настройки аккаунта сохранены.'))}catch(e:any){notify(e.message,true)}finally{busy.value=false}}
async function resend(){try{const r=await api('/auth/resend-verification',{method:'POST'});notify(r.delivery_enabled?t('Verification email queued.','Письмо для подтверждения поставлено в очередь.'):t('Email delivery is disabled in this environment.','Отправка писем в этом окружении отключена.'),!r.delivery_enabled)}catch(e:any){notify(e.message,true)}}
async function saveSchedules(){try{state.workspace=await api(wp('/settings'),{method:'PATCH',body:{scheduled_briefs:schedules.value}});notify(t('Brief schedule saved.','Расписание сводок сохранено.'))}catch(e:any){notify(e.message,true)}}
async function logout(){await api('/auth/logout',{method:'POST'});state.user=null;state.workspace=null;router.push('/')}
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{t('MAKE SIGNALDESK YOURS','SIGNALDESK ПОД ВАШИ ЗАДАЧИ')}}</span><h1>{{t('A workspace that works for you.','Пространство для вашей работы.')}}</h1><p>{{t('The right people, perspectives and preferences.','Нужные люди, роли и настройки.')}}</p></div><RouterLink to="/onboarding?new=1" class="btn secondary"><Icon name="Plus" :size="16"/>{{t('New workspace','Новое пространство')}}</RouterLink></div><div class="tabs page-tabs"><button v-for="a in tabs" :key="a.id" :class="{active:tab===a.id}" @click="tab=a.id"><Icon :name="a.icon" :size="16"/>{{a.label}}</button></div>
<div v-if="tab==='team'" class="settings-grid"><section><div class="card"><div class="card-heading"><div><h2>{{t('People in your workspace','Участники пространства')}}</h2><p>{{t('Access roles and decision roles are independent.','Права доступа и бизнес-роли настраиваются отдельно.')}}</p></div><span class="count-pill">{{team.members.length}}</span></div><div class="team-table"><div v-for="m in team.members" :key="m.id" class="team-row"><span class="avatar">{{m.name.slice(0,1)}}</span><div class="member-info"><strong>{{m.name}} <span v-if="m.user_id===state.user.id" class="muted small">({{t('you','вы')}})</span></strong><small>{{m.email}}</small></div><select v-if="adminAccess&&m.role!=='owner'&&m.user_id!==state.user.id" :value="m.role" @change="roleChange(m,$event)" :aria-label="t('Access role for ','Роль доступа для ')+m.name"><option value="admin" v-if="state.workspace.role==='owner'">{{t('Administrator','Администратор')}}</option><option value="analyst">{{t('Analyst','Аналитик')}}</option><option value="viewer">{{t('Viewer','Наблюдатель')}}</option></select><span v-else class="badge neutral">{{t({owner:'Owner',admin:'Admin',analyst:'Analyst',viewer:'Viewer'}[m.role],{owner:'Владелец',admin:'Администратор',analyst:'Аналитик',viewer:'Наблюдатель'}[m.role])}}</span><button v-if="adminAccess&&m.role!=='owner'&&m.user_id!==state.user.id" class="icon-btn" @click="remove(m)" :aria-label="t('Remove ','Удалить ')+m.name"><Icon name="UserMinus" :size="16"/></button></div></div></div><section v-if="team.invitations.length" class="card mt-lg"><h3>{{t('Invitations','Приглашения')}}</h3><div v-for="i in team.invitations" :key="i.id" class="invite-row"><Icon name="Mail" :size="17"/><div><strong>{{i.email}}</strong><span>{{i.role}} · {{t('Expires','Истекает')}} {{fmt(i.expires_at)}}</span></div><span class="badge neutral">{{i.accepted?t('Accepted','Принято'):t('Pending','Ожидает')}}</span></div></section><section class="card mt-lg"><h3>{{t('What each role can do','Что может каждая роль')}}</h3><div class="role-guide" v-for="r in [{en:'Owner',ru:'Владелец',d:t('Manage workspace, team, monitoring and private model credentials.','Управляет пространством, командой, мониторингом и ключами моделей.')},{en:'Administrator',ru:'Администратор',d:t('Manage monitoring and invite analysts or viewers.','Настраивает мониторинг, приглашает аналитиков и наблюдателей.')},{en:'Analyst',ru:'Аналитик',d:t('Edit company context, manage sources, run analysis and prepare briefs.','Редактирует контекст, источники, запускает анализ и создаёт сводки.')},{en:'Viewer',ru:'Наблюдатель',d:t('Read insights, ask questions, save events and provide feedback.','Читает аналитику, задаёт вопросы, сохраняет события и оставляет отзывы.')} ]" :key="r.en"><strong>{{t(r.en,r.ru)}}</strong><p>{{r.d}}</p></div></section></section><aside v-if="adminAccess" class="card settings-aside"><span class="form-section-icon"><Icon name="UserPlus" :size="23"/></span><h2>{{t('Invite a perspective','Добавьте взгляд коллеги')}}</h2><p class="muted small">{{t('Bring your team into the same company context.','Объедините команду вокруг контекста компании.')}}</p><div v-if="state.workspace.demo" class="notice">{{t('Create a real workspace to invite your team. Demo workspaces are personal sandboxes.','Создайте рабочее пространство для приглашения команды. Демо доступно только вам.')}}</div><div v-else-if="!state.user.verified" class="notice"><div>{{t('Confirm your email to send invitations.','Подтвердите почту, чтобы приглашать коллег.')}}<button class="text-link mt-sm" @click="resend">{{t('Resend confirmation','Отправить подтверждение')}}</button></div></div><form @submit.prevent="sendInvite" class="form-stack mt-sm"><label>{{t('Work email','Рабочая почта')}}<input v-model="invite.email" type="email" placeholder="colleague@company.com" required></label><label>{{t('Workspace role','Роль доступа')}}<select v-model="invite.role"><option value="viewer">{{t('Viewer','Наблюдатель')}}</option><option value="analyst">{{t('Analyst','Аналитик')}}</option><option v-if="state.workspace.role==='owner'" value="admin">{{t('Administrator','Администратор')}}</option></select></label><button class="btn primary full" :disabled="busy||state.workspace.demo||!state.user.verified"><Icon name="Send" :size="16"/>{{t('Send invitation','Отправить приглашение')}}</button></form><div v-if="inviteUrl" class="invite-result"><label>{{t('Invitation link','Ссылка приглашения')}}<input :value="inviteUrl" readonly @focus="($event.target as HTMLInputElement).select()"></label></div></aside></div>
<section v-else-if="tab==='model'" class="card settings-narrow"><div class="card-heading"><div><h2>{{t('The model behind your analysis','Модель для вашей аналитики')}}</h2><p>{{t('The case connection uses the approved model gateway. Private connections stay within this workspace.','Подключение кейса использует разрешённый шлюз. Собственные подключения доступны только в вашем пространстве.')}}</p></div><span class="stat-icon purple"><Icon name="Cpu" :size="21"/></span></div><div class="notice" v-if="state.workspace.role!=='owner'"><Icon name="Lock" :size="17"/>{{t('Only the workspace owner can change model credentials.','Ключи модели может менять только владелец пространства.')}}</div><form class="form-stack" @submit.prevent="saveModel"><label>{{t('Connection type','Тип подключения')}}<select v-model="model.mode" :disabled="state.workspace.role!=='owner'"><option value="case">{{t('Hackathon · approved models','Хакатон · разрешённые модели')}}</option><option value="custom">{{t('Private OpenAI-compatible connection','Собственное OpenAI-совместимое API')}}</option></select></label><template v-if="model.mode==='case'"><label>{{t('Approved model','Разрешённая модель')}}<select v-model="model.model" :disabled="state.workspace.role!=='owner'"><option v-for="m in state.config.approved_models" :key="m" :value="m">{{m}}</option></select></label><div class="model-facts"><div><span>{{t('Gateway','Шлюз')}}</span><strong>{{t('Hackathon API','API хакатона')}}</strong></div><div><span>{{t('Shared budget','Общий бюджет')}}</span><strong>500 RUB / {{t('day','день')}}</strong></div><div><span>{{t('Budget reset','Сброс бюджета')}}</span><strong>03:00 MSK</strong></div></div></template><template v-else><div class="notice"><Icon name="Info" :size="18"/>{{t('Use this for a private or development connection. For case evaluation, select an approved model and return to the hackathon gateway.','Для собственной среды или разработки. Для оценки кейса выберите разрешённую модель и шлюз хакатона.')}}</div><label>Base URL<input v-model="model.base_url" type="url" placeholder="https://your-provider.example/v1" :disabled="state.workspace.role!=='owner'" required></label><label>{{t('Model ID','ID модели')}}<input v-model="model.model" placeholder="provider/model-id" :disabled="state.workspace.role!=='owner'" required></label><label>API key<input v-model="model.api_key" type="password" autocomplete="off" :placeholder="state.workspace.settings.model?.key_configured?t('Key saved · leave blank to keep it','Ключ сохранён · оставьте пустым для сохранения'):'sk-…'" :disabled="state.workspace.role!=='owner'"><small>{{t('Write-only. Encrypted on the server. Never included in browser responses or workspace exports.','Только для записи. Хранится зашифрованным на сервере. Не возвращается в браузер и экспорт.')}}</small></label></template><div v-if="state.workspace.role==='owner'" class="row gap-sm"><button class="btn primary" :disabled="busy">{{t('Save connection','Сохранить подключение')}}</button><button type="button" class="btn secondary" :disabled="busy" @click="test"><Icon :name="busy?'LoaderCircle':'PlugZap'" :class="{spin:busy}" :size="16"/>{{t('Test saved connection','Проверить подключение')}}</button></div><div v-if="testResult" class="notice success-notice"><Icon name="CheckCircle2" :size="18"/>{{t('Connection responded successfully','Подключение ответило успешно')}} · {{testResult.model}}</div></form></section>
<section v-else-if="tab==='delivery'" class="card settings-narrow"><h2>{{t('Intelligence, on a rhythm','Аналитика по расписанию')}}</h2><p class="muted">{{t('Scheduled briefs turn verified workspace events into a recurring decision agenda. Automatic monitoring must be enabled.','Сводки превращают проверенные события в регулярную повестку решений. Автоматический мониторинг должен быть включён.')}}</p><form @submit.prevent="saveSchedules" class="form-stack"><label v-for="p in [{id:'day',title:t('Daily brief','Дневная сводка'),when:t('Every day at 10:00 Moscow time','Каждый день в 10:00 МСК')},{id:'week',title:t('Weekly brief','Недельная сводка'),when:t('Mondays at 10:00 Moscow time','По понедельникам в 10:00 МСК')},{id:'month',title:t('Monthly brief','Месячная сводка'),when:t('First day of the month at 10:00 Moscow time','Первого числа месяца в 10:00 МСК')} ]" :key="p.id" class="schedule-option"><input type="checkbox" :value="p.id" v-model="schedules" :disabled="!adminAccess"><span><strong>{{p.title}}</strong><small>{{p.when}}</small></span><Icon name="CalendarClock" :size="19"/></label><div class="notice"><Icon name="Mail" :size="18"/>{{t('Delivery is personal. Turn on email briefs in My account and confirm your email address.','Доставка персональная. Включите письма со сводками в разделе «Мой аккаунт» и подтвердите почту.')}}</div><button v-if="adminAccess" class="btn primary" :disabled="state.workspace.demo">{{t('Save schedule','Сохранить расписание')}}</button><p v-if="state.workspace.demo" class="small muted">{{t('Scheduled runs are disabled for demonstration workspaces.','В демо запуски по расписанию отключены.')}}</p></form></section>
<section v-else class="card settings-narrow"><div class="card-heading"><div><h2>{{t('Your account','Ваш аккаунт')}}</h2><p>{{state.user.email}}</p></div><span class="avatar large-avatar">{{state.user.name.slice(0,1)}}</span></div><div v-if="!state.user.verified" class="notice"><Icon name="Mail" :size="18"/><div>{{t('Confirm your email to activate email notifications.','Подтвердите почту для активации уведомлений.')}}<button class="text-link" @click="resend">{{t('Resend verification','Отправить подтверждение')}}</button></div></div><form @submit.prevent="saveAccount" class="form-stack mt-lg"><label>{{t('Display name','Ваше имя')}}<input v-model="displayName" required maxlength="100"></label><div class="form-divider"></div><h3>{{t('Email preferences','Настройки писем')}}</h3><label class="checkbox-label"><input type="checkbox" v-model="prefs.email_alerts">{{t('Important business signals','Важные бизнес-сигналы')}}</label><label class="checkbox-label"><input type="checkbox" v-model="prefs.email_briefs">{{t('Scheduled executive briefs','Регулярные бизнес-сводки')}}</label><p class="small muted">{{t('Sent through SendPulse as SignalDesk from maksim@subschool.us. You can turn delivery off here at any time.','Письма SignalDesk отправляются через SendPulse с maksim@subschool.us. Доставку можно отключить здесь в любое время.')}}</p><p v-if="!state.config.email_enabled" class="notice">{{t('Email delivery is currently disabled in this environment. Preferences are saved for when delivery is enabled.','Отправка писем в этом окружении отключена. Настройки сохранятся до её включения.')}}</p><button class="btn primary" :disabled="busy">{{t('Save preferences','Сохранить настройки')}}</button></form><div class="form-divider mt-lg"></div><div class="row between wrap"><a v-if="adminAccess" :href="'/api'+wp('/export')" class="btn secondary"><Icon name="Download" :size="16"/>{{t('Export workspace data','Экспорт данных пространства')}}</a><button class="btn ghost" @click="logout"><Icon name="LogOut" :size="16"/>{{t('Sign out','Выйти')}}</button></div></section>
</template>
